import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

it('preserves an undefined rejection as the hook error cause [specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield -- The provider fails before producing a chunk.
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw undefined;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const errors: Error[] = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test assistant'}), undefined, {
    hooks: {
      onError: async (_session, error) => {
        errors.push(error);
      },
    },
  });

  const outcome = await orchestrator.processMessage(session).then(
    () => ({rejected: false, reason: 'resolved'}),
    (reason: unknown) => ({rejected: true, reason})
  );

  expect({
    outcome,
    count: errors.length,
    isError: errors[0] instanceof Error,
    message: errors[0]?.message,
    hasCause: Object.hasOwn(errors[0] ?? {}, 'cause'),
    cause: errors[0]?.cause,
  }).toEqual({
    outcome: {rejected: true, reason: undefined},
    count: 1,
    isError: true,
    message: 'undefined',
    hasCause: true,
    cause: undefined,
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"

